use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn clip_spec(x: i8, min_val: i8, max_val: i8) -> i8 {
    if min_val <= max_val {
        if x < min_val {
            min_val
        } else if x > max_val {
            max_val
        } else {
            x
        }
    } else {
        max_val
    }
}

fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> (result: Vec<i8>)
    ensures
        result.len() == arr.len(),
        forall|i: int| 0 <= i < arr.len() ==> 
            result[i] == clip_spec(arr[i], min_val, max_val),
{
    let mut result_vec = Vec::new();
    let mut idx: usize = 0;
    
    while idx < arr.len()
        invariant
            0 <= idx <= arr.len(),
            result_vec.len() == idx,
            forall|i: int| 0 <= i < idx ==> 
                result_vec[i] == clip_spec(arr[i], min_val, max_val),
        decreases arr.len() - idx,
    {
        let elem = arr[idx];
        let clipped_elem = if min_val <= max_val {
            if elem < min_val {
                min_val
            } else if elem > max_val {
                max_val
            } else {
                elem
            }
        } else {
            max_val
        };
        
        result_vec.push(clipped_elem);
        idx = idx + 1;
    }
    
    result_vec
}

}
